"""Application errors rendered as stable JSON error responses."""

from __future__ import annotations


class APIError(Exception):
    def __init__(self, status_code: int, code: str, message: str) -> None:
        self.status_code = status_code
        self.code = code
        self.message = message
        super().__init__(message)


class NotFoundError(APIError):
    """A referenced dataset, schema version or field does not exist (404)."""

    def __init__(self, message: str) -> None:
        super().__init__(404, "not_found", message)


class ConflictError(APIError):
    """The request conflicts with already stored state (409)."""

    def __init__(self, message: str) -> None:
        super().__init__(409, "conflict", message)


class RequestInvalidError(APIError):
    """The request is structurally or semantically invalid (422)."""

    def __init__(self, message: str) -> None:
        super().__init__(422, "validation_error", message)

        yield
    finally:
        lock.release()


@app.post(
    f"{SNAPSHOTS_PATH}/retention-sweep",
    response_model=RetentionSweepResponse,
)
def sweep_snapshot_retention(
    request: Request,
    dataset_name: str,
    version: int,
    body: bytes = Depends(_read_request_body),
    _sweep: None = Depends(_retention_sweep_guard),
    conn=Depends(get_db),
) -> Response:
    # The body is parsed in the repository (after the path dataset/version and
    # the version's retention policy resolve) so an unknown dataset, version
    # or missing policy stays a 404 ahead of every body/query shape check
    # (all 422). Concurrent sweeps of the same version have a single winner;
    # the loser is a 409 and changes nothing. Every rejection writes nothing.
    sweep = RetentionSweepResponse(
        **repository.sweep_snapshot_retention(
            conn,
            dataset_name,
            version,
            body,
            query_keys=tuple(request.query_params.keys()),
        )
    )
    payload = json.dumps(
        sweep.model_dump(mode="json"),
        separators=(",", ":"),
        ensure_ascii=False,
    )
    return Response(content=payload + "\n", media_type="application/json")


# Read-only preview of the batch retention sweep, appended one segment after
# the sweep address and accepting GET only. It scans the version's existing
# snapshots with exactly the sweep's classification but never opens a request
# or writes anything. The body is serialized directly (rather than through the
# default JSON response) so the key order is fixed, the whitespace is compact
# and the document ends with exactly one newline.
@app.get(
    f"{SNAPSHOTS_PATH}/retention-sweep/preview",
    response_model=RetentionSweepPreviewResponse,
)
def preview_snapshot_retention_sweep(
    request: Request,
    dataset_name: str,
    version: int,
    body: bytes = Depends(_read_request_body),
    conn=Depends(get_db),
) -> Response:
    # The path dataset/version and the version's retention policy resolve
    # first (404), ahead of every request-shape check; only afterwards are any
    # body bytes (whitespace-only included) or query parameters rejected
    # (422). The preview is strictly read-only: its classification and statuses
    # match the requests a subsequent real sweep would open.
    preview = RetentionSweepPreviewResponse(
        **repository.preview_snapshot_retention_sweep(
            conn,
            dataset_name,
            version,
            body=body,
            query_keys=tuple(request.query_params.keys()),
        )
    )
    payload = json.dumps(
        preview.model_dump(mode="json"),
        separators=(",", ":"),
        ensure_ascii=False,
    )
    return Response(content=payload + "\n", media_type="application/json")


